// Port of the day-level part of core/src/jpl.rs — method "jpl" (docs/03 §17).
//
// The Rust core holds the DE441 instant table (core/data/jpl_events.bin, 0.01 s TT) and derives, with ΔT and the
// time-zone rules, (a) the calendar day of every new moon and (b) for every solar term the day D = first day whose
// 00:00 is at or after the term instant. tsport/src/jpl_days.ts is that day table, generated by the Rust core
// (`lvhv-dump jpl-days-ts`; core/tests/jpl_ts.rs fails if it is stale). Using only days keeps the PWA small (P3)
// and makes TS ≡ Rust by construction; check-parity.sh verifies every day 1900–3000 byte for byte.
// Lookups outside the table throw LvhvError OutOfRange (never a fallback to "precise").

import { outOfRange } from "./error.ts";
import { JPL_DAYS } from "./jpl_days.ts";

interface DayTable {
  k0: number;
  socDays: Int32Array;
  i0: number;
  tkDays: Int32Array;
}

let cached: DayTable | undefined;

function table(): DayTable {
  if (cached !== undefined) return cached;
  const sd = JPL_DAYS.socDelta;
  const socDays = new Int32Array(sd.length + 1);
  socDays[0] = JPL_DAYS.socDay0;
  for (let i = 0; i < sd.length; i++) socDays[i + 1] = socDays[i] + (sd.charCodeAt(i) === 48 ? 29 : 30);
  const td = JPL_DAYS.tkDelta;
  const tkDays = new Int32Array(td.length + 1);
  tkDays[0] = JPL_DAYS.tkDay0;
  for (let i = 0; i < td.length; i++) tkDays[i + 1] = tkDays[i] + 10 + (td.charCodeAt(i) - 48);
  cached = { k0: JPL_DAYS.k0, socDays, i0: JPL_DAYS.i0, tkDays };
  return cached;
}

/** Calendar day (JDN) of new moon k (HND index) — Rust `local_day_of(jpl::new_moon_ut(k))`. */
export function jplNewMoonDay(k: number): number {
  const t = table();
  const j = k - t.k0;
  if (!Number.isSafeInteger(j) || j < 0 || j >= t.socDays.length) throw outOfRange();
  return t.socDays[j];
}

/** Rust `jpl::term_at(local_midnight_ut(jdn))`: index (0..23) of the latest term with D ≤ jdn. */
export function jplTermAtMidnight(jdn: number): number {
  const t = table();
  const n = t.tkDays.length;
  // Rust: valid iff first instant ≤ midnight < last instant ⇔ D_first ≤ jdn < D_last.
  if (!Number.isSafeInteger(jdn) || jdn < t.tkDays[0] || jdn >= t.tkDays[n - 1]) throw outOfRange();
  let lo = 0;
  let hi = n;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (t.tkDays[mid] <= jdn) lo = mid + 1;
    else hi = mid;
  }
  return (t.i0 + lo - 1) % 24;
}
